(function(){if(document.getElementById('env-css'))return;const st=document.createElement('style');st.id='env-css';st.textContent="/* ENVIRONNEMENT — sites ICPE (carte + échéances) · V0.1 */\n.env-top{display:flex;align-items:center;gap:12px;flex-wrap:wrap;margin-bottom:14px}\n.env-top h2{font-size:24px;color:var(--marine);margin-right:auto}\n.env-pastille{display:inline-block;min-width:18px;padding:1px 5px;border-radius:9px;background:var(--mid);color:#fff;font-size:11px;line-height:16px;text-align:center}\n.env-pastille.tard{background:var(--warn)}\n.env-grid{display:grid;grid-template-columns:minmax(0,1.25fr) minmax(320px,1fr);gap:16px;align-items:start}\n.env-grid.cal{grid-template-columns:minmax(0,1.7fr) minmax(320px,1fr)}\n@media(max-width:980px){.env-grid,.env-grid.cal{grid-template-columns:1fr}}\n.env-side .card{margin-bottom:0}\n.env-side h2{font-size:20px;color:var(--marine);margin-bottom:10px}\n/* --- carte --- */\n.env-cc{padding:12px 14px}\nsvg.env-carte{display:block;width:100%;height:auto;max-height:72vh}\n.env-deps path{fill:#e3edf7;stroke:#fff;stroke-width:.7;transition:fill .15s}\n.env-deps path:hover{fill:#d2e2f2}\n.env-regs path{fill:none;stroke:#9db6cf;stroke-width:1.1;pointer-events:none}\n.env-pt{cursor:pointer;outline:none}\n.env-pt circle{stroke:#fff;stroke-width:1.8;filter:drop-shadow(0 1px 2px rgba(15,45,80,.35))}\n.env-pt text{font:700 8.5px \"Barlow\",Arial,sans-serif;fill:#fff;text-anchor:middle;pointer-events:none}\n.env-pt.projet circle:not(.halo){stroke-dasharray:3.2 2.2;stroke:#14283e}\n.env-pt.cess circle:not(.halo){opacity:.45}\n.env-pt .halo{fill:rgba(31,111,178,.16);stroke:var(--cyan);stroke-width:1.6;filter:none}\n.env-pt:hover circle:not(.halo),.env-pt:focus circle:not(.halo){stroke:#14283e}\n.env-leg{display:flex;flex-wrap:wrap;gap:6px;align-items:center;margin-top:8px}\n.env-leg button{display:inline-flex;align-items:center;gap:6px;border:1px solid var(--line);background:#fff;border-radius:20px;padding:4px 10px 4px 4px;font:600 12.5px inherit;font-family:inherit;color:var(--txt);cursor:pointer}\n.env-leg button.on{border-color:var(--cyan);background:rgba(31,111,178,.10)}\n.env-leg button b{color:var(--muted)}\n.env-leg i,.env-s i{display:inline-flex;align-items:center;justify-content:center;width:22px;height:22px;border-radius:50%;color:#fff;font:700 10px \"Barlow\",Arial,sans-serif;font-style:normal;flex:none}\n.env-leg-n{font-size:12px;color:var(--muted);display:inline-flex;align-items:center;gap:5px;margin-left:4px}\n.env-leg-n .pj{width:14px;height:14px;border:1.6px dashed #14283e;background:#cfdcea}\n/* --- liste des sites --- */\n.env-s{display:flex;align-items:center;gap:10px;width:100%;text-align:left;border:1px solid var(--line);background:#fff;border-radius:12px;padding:9px 11px;margin-bottom:7px;cursor:pointer;font-family:inherit;color:var(--txt)}\n.env-s:hover{border-color:var(--line2);background:var(--glass2)}\n.env-s span{flex:1;min-width:0}.env-s span b{display:block;font-size:14.5px}.env-s span em{font-style:normal;font-size:12.5px;color:var(--muted)}\n.env-s u{text-decoration:none;font-size:11px;line-height:1.15;text-align:center;border-radius:8px;padding:4px 8px;background:var(--glass2);color:var(--muted);font-weight:600}\n.env-s u.tard{background:var(--warn-bg);color:var(--warn)}.env-s u.proche{background:rgba(194,90,8,.12);color:var(--accent)}.env-s u.an{background:var(--mid-bg);color:var(--mid)}\n/* --- fiche --- */\n.env-fh{display:flex;justify-content:space-between;gap:8px;margin-bottom:10px}\n.env-fiche h2{font-size:23px}.env-fiche h3{font-size:17px;margin:16px 0 8px;color:var(--marine)}\n.env-chips{display:flex;flex-wrap:wrap;gap:6px;margin:4px 0 12px}\n.env-chip{font-size:12px;font-weight:700;padding:3px 10px;border-radius:20px;color:var(--c);background:color-mix(in srgb,var(--c) 11%,#fff);border:1px solid color-mix(in srgb,var(--c) 30%,#fff)}\n.env-fin{display:flex;align-items:baseline;gap:10px;flex-wrap:wrap;border-radius:12px;padding:10px 12px;margin-bottom:10px;background:var(--glass2);border:1px solid var(--line)}\n.env-fin span{font-size:12px;text-transform:uppercase;letter-spacing:.5px;color:var(--muted);font-weight:600;width:100%}\n.env-fin b{font:700 22px \"Barlow Condensed\",\"Barlow\",sans-serif}.env-fin em{font-style:normal;font-size:13px;font-weight:600;color:var(--muted)}\n.env-fin.tard{background:var(--warn-bg);border-color:rgba(194,43,34,.3)}.env-fin.tard b,.env-fin.tard em{color:var(--warn)}\n.env-fin.proche{background:rgba(194,90,8,.09);border-color:rgba(194,90,8,.3)}.env-fin.proche em{color:var(--accent)}\n.env-fin.an{background:var(--mid-bg);border-color:rgba(180,114,10,.28)}.env-fin.an em{color:var(--mid)}\n.env-l{display:flex;gap:10px;padding:6px 0;border-bottom:1px solid var(--line);font-size:14px}\n.env-l span{flex:0 0 42%;color:var(--muted)}.env-l b{flex:1;font-weight:600;min-width:0;overflow-wrap:anywhere}\n.env-note{font-size:13.5px;color:var(--muted);background:var(--glass2);border-radius:10px;padding:8px 10px;margin:10px 0 0}\n.env-liens{display:flex;flex-wrap:wrap;gap:8px;margin-top:12px}.env-liens a{text-decoration:none}\n/* --- échéances --- */\n.env-e{display:flex;align-items:center;gap:10px;border:1px solid var(--line);border-radius:12px;padding:8px 10px;margin-bottom:7px;background:#fff}\n.env-e[onclick]{cursor:pointer}.env-e[onclick]:hover{border-color:var(--line2)}\n.env-e>i{width:6px;align-self:stretch;border-radius:3px;flex:none}\n.env-ed{flex:0 0 96px}.env-ed b{display:block;font-size:13.5px}.env-ed em{font-style:normal;font-size:11.5px;font-weight:600;color:var(--muted)}\n.env-et{flex:1;min-width:0;font-size:13px}.env-et b{display:block;font-size:14px}.env-et span{color:var(--muted)}\n.env-e.tard{background:var(--warn-bg);border-color:rgba(194,43,34,.3)}.env-e.tard .env-ed em{color:var(--warn)}\n.env-e.proche .env-ed em{color:var(--accent)}.env-e.an .env-ed em{color:var(--mid)}\n.env-e.vise{box-shadow:0 0 0 2px var(--cyan)}\n.env-rt{font-size:12px;font-weight:700;text-transform:uppercase;letter-spacing:.6px;color:var(--cyan);margin:12px 0 7px;display:flex;align-items:center;justify-content:space-between;gap:8px}\n.env-rt:first-of-type{margin-top:0}.env-rt.tard{color:var(--warn)}\n.env-recap{max-height:78vh;overflow:auto}\n.env-an{display:flex;align-items:center;gap:10px;flex-wrap:wrap;margin-bottom:12px}\n.env-an h2{font-size:26px;color:var(--marine);min-width:62px;text-align:center}\n.env-leg2{margin-left:auto;display:flex;flex-wrap:wrap;gap:12px;font-size:12px;color:var(--muted)}\n.env-leg2 span{display:inline-flex;align-items:center;gap:5px}.env-leg2 i{width:10px;height:10px;border-radius:50%}\n.env-cal{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px}\n@media(max-width:1250px){.env-cal{grid-template-columns:repeat(3,minmax(0,1fr))}}\n@media(max-width:620px){.env-cal{grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}}\n.env-m{border:1px solid var(--line);border-radius:12px;padding:8px 8px 9px;background:#fff}\n.env-m.a{border-color:var(--line2)}\n.env-mt{font:700 14px \"Barlow Condensed\",\"Barlow\",sans-serif;letter-spacing:.4px;text-transform:uppercase;color:var(--muted);display:flex;justify-content:space-between;align-items:center;margin-bottom:5px}\n.env-m.a .env-mt{color:var(--marine)}\n.env-mt b{background:var(--cyan);color:#fff;border-radius:9px;min-width:18px;padding:0 5px;font:700 11px/17px \"Barlow\",sans-serif;text-align:center}\n.env-mg{display:grid;grid-template-columns:repeat(7,1fr);gap:1px;font-size:11px;text-align:center}\n.env-mg s{text-decoration:none;color:var(--faint);font-size:9.5px;font-weight:600}\n.env-mg span{line-height:20px;color:var(--faint)}\n.env-mg span.auj{color:var(--txt);font-weight:700;box-shadow:inset 0 0 0 1.5px var(--txt);border-radius:6px}\n.env-mg .j{position:relative;border:none;background:var(--c);color:#fff;font:700 11px/20px \"Barlow\",sans-serif;border-radius:6px;padding:0;cursor:pointer}\n.env-mg .j.on{box-shadow:0 0 0 2px #fff,0 0 0 4px var(--c)}\n.env-mg .j sup{position:absolute;top:-5px;right:-4px;background:#14283e;color:#fff;border-radius:7px;font-size:8px;line-height:11px;min-width:11px}\n/* --- formulaire --- */\n.env-2{display:flex;gap:10px;flex-wrap:wrap}.env-2>div{flex:1;min-width:150px}\n.env-form h3{font-size:17px;color:var(--marine);margin-bottom:8px}\n.env-fe{display:grid;grid-template-columns:150px minmax(0,1fr) 150px 150px auto;gap:6px;margin-bottom:6px;align-items:center}\n@media(max-width:700px){.env-fe{grid-template-columns:1fr 1fr;border:1px solid var(--line);border-radius:10px;padding:6px}.env-fe .fe-lib{grid-column:1/-1}}\n.env-form .env-fe select,.env-form .env-fe input{padding:8px 9px;font-size:13.5px}\n/* --- V0.2 : oui / non, pastilles écartées --- */\n.env-pt text.p{font-size:6.6px}\n.env-fil{stroke:#14283e;stroke-width:.6;opacity:.55}.env-vrai{fill:#14283e}\n.env-on{display:grid;grid-template-columns:1fr 1fr;gap:7px;margin:2px 0 12px}\n.env-on div{border-radius:11px;padding:8px 11px;border:1px solid var(--line);background:var(--glass2);display:flex;flex-direction:column;gap:1px}\n.env-on b{font:700 17px \"Barlow Condensed\",\"Barlow\",sans-serif;letter-spacing:.3px;color:var(--faint)}\n.env-on span{font-size:12.5px;color:var(--muted);font-weight:600}\n.env-on .oui{background:var(--ok-bg);border-color:rgba(21,138,82,.32)}.env-on .oui b{color:var(--ok)}\n.env-on .non{background:var(--warn-bg);border-color:rgba(194,43,34,.3)}.env-on .non b{color:var(--warn)}\n.env-s u.ok{background:var(--ok-bg);color:var(--ok);font-size:14px}.env-s u.ko{background:var(--warn-bg);color:var(--warn);font-size:14px}\n.env-liste{max-height:78vh;overflow:auto}\n.env-zm{display:flex;justify-content:flex-end;margin-bottom:6px}.env-zm .seg button{padding:6px 12px;font-size:12.5px}\nsvg.env-carte.zoom .env-deps path{stroke-width:calc(.7px*var(--f))}svg.env-carte.zoom .env-regs path{stroke-width:calc(1.1px*var(--f))}\nsvg.env-carte.zoom .env-fil{stroke-width:calc(.6px*var(--f))}\n/* --- V0.3 : convention --- */\n.env-cv{border-radius:12px;padding:9px 12px;margin-bottom:10px;background:rgba(194,90,8,.07);border:1px solid rgba(194,90,8,.26);display:flex;flex-wrap:wrap;align-items:baseline;gap:4px 10px}\n.env-cv span{font-size:12px;text-transform:uppercase;letter-spacing:.5px;color:var(--accent);font-weight:700;width:100%}\n.env-cv b{font:700 19px \"Barlow Condensed\",\"Barlow\",sans-serif}.env-cv b.ech{color:var(--muted)}\n.env-cv em{font-style:normal;font-size:12.5px;color:var(--muted);font-weight:600;width:100%}\n";document.head.appendChild(st)})();

/* ---------- données ---------- */
function envSites(){
  let l=Array.isArray(state.sitesEnv)?state.sitesEnv.filter(s=>s&&!s.supprime):[];
  if(typeof agenceChoisie==='string'&&agenceChoisie)l=l.filter(s=>!s.agence||s.agence===agenceChoisie);
  return l.sort((a,b)=>String(a.nom).localeCompare(String(b.nom),'fr'))}
function envSite(id){return (state.sitesEnv||[]).find(s=>s.id===id)||null}
function envJours(iso){if(!iso)return null;return Math.round((new Date(iso+'T00:00')-new Date(todayISO+'T00:00'))/864e5)}
function envDans(j){
  if(j===null)return '';
  if(j<0)return 'en retard de '+envDuree(-j);
  if(j===0)return 'aujourd’hui';
  return 'dans '+envDuree(j)}
function envDuree(j){if(j<60)return j+' j';if(j<730)return Math.round(j/30.4)+' mois';const a=j/365.25;return (Math.round(a*2)/2).toLocaleString('fr-FR')+' ans'}
function envTon(j){return j===null?'':j<0?'tard':j<=90?'proche':j<=365?'an':'loin'}
/* toutes les échéances à venir (ou en retard), tous sites confondus */
function envEcheances(){
  const out=[];
  envSites().forEach(s=>{
    if(s.statut==='cessation')return;
    if(s.arreteFin)out.push({site:s,type:'arrete',lib:'Fin de validité de l’arrêté'+(s.arreteNum?' n° '+s.arreteNum:''),date:s.arreteFin});
    if(s.renouvDepot)out.push({site:s,type:'arrete',lib:'Date limite de dépôt du dossier de renouvellement',date:s.renouvDepot});
    const cv=envConv(s);if(cv&&cv.date)out.push({site:s,type:'conv',lib:cv.lib,date:cv.date});
    (s.echeances||[]).forEach(e=>{if(e&&e.date&&!e.fait)out.push({site:s,type:e.type==='libre'?'libre':'suivi',lib:e.lib||'Échéance',date:e.date,per:Number(e.per)||0,id:e.id})});
  });
  return out.sort((a,b)=>a.date<b.date?-1:a.date>b.date?1:0)}

/* convention avec le propriétaire. Dans le calendrier :
   · convention en cours → sa date de fin (avec la date limite de préavis si elle est connue) ;
   · convention échue + tacite reconduction + site exploitable → la prochaine date anniversaire
     (hypothèse : reconduction d'année en année) ;
   · convention échue sans reconduction, ou site non exploitable → rien (la fiche le dit). */
function envMoisPreavis(t){const m=String(t||'').toLowerCase().match(/(\d+)\s*(an|mois)/);return m?Number(m[1])*(m[2]==='an'?12:1):0}
function envConv(s){
  if(s.okConv!=='oui'||!s.convFin)return null;
  const j=envJours(s.convFin),pre=envMoisPreavis(s.convPreavis);
  const avant=(iso)=>{if(!pre)return '';const d=new Date(iso+'T12:00'),jr=d.getDate();d.setMonth(d.getMonth()-pre);if(d.getDate()!==jr)d.setDate(0);return ' — préavis '+s.convPreavis+' : avant le '+frDate(d.toISOString().slice(0,10))};
  if(j>=0)return {etat:'cours',date:s.okExploit==='non'?'':s.convFin,lib:'Fin de la convention avec le propriétaire'+avant(s.convFin)};
  if(s.convTacite==='oui'&&s.okExploit!=='non'){
    const d=new Date(s.convFin+'T12:00');while(d.toISOString().slice(0,10)<todayISO)d.setFullYear(d.getFullYear()+1);
    const a=d.toISOString().slice(0,10);return {etat:'reconduite',date:a,lib:'Date anniversaire de la convention (tacite reconduction)'+avant(a)}}
  return {etat:'echue',date:'',lib:''}}

/* ---------- carte ---------- */
function envXY(lat,lon){const p=CARTE_FR.proj;return [(lon-p.lon0)*p.c*p.k,(p.lat0-lat)*p.k]}
function envCarte(sites){
  /* « Zoom sur les sites » : la vue se resserre sur l'emprise des sites affichés ; les
     pastilles gardent la même taille à l'écran (facteur f). */
  let b=CARTE_FR.box,f=1;
  const geo=sites.filter(s=>s.lat&&s.lon).map(s=>envXY(Number(s.lat),Number(s.lon)));
  if(envVue.zoom&&geo.length){
    const xs=geo.map(p=>p[0]),ys=geo.map(p=>p[1]);let x0=Math.min(...xs),x1=Math.max(...xs),y0=Math.min(...ys),y1=Math.max(...ys);
    let w=Math.max(x1-x0,90)*1.24,hh=Math.max(y1-y0,90)*1.24;const ratio=b[2]/b[3];
    if(w/hh<ratio)w=hh*ratio;else hh=w/ratio;
    b=[(x0+x1)/2-w/2,(y0+y1)/2-hh/2,w,hh].map(v=>Math.round(v*10)/10);f=w/CARTE_FR.box[2]}
  let h='<svg class="env-carte'+(envVue.zoom?' zoom':'')+'" style="--f:'+f.toFixed(3)+'" viewBox="'+b.join(' ')+'" role="img" aria-label="Carte de France des sites ICPE">';
  h+='<g class="env-deps">'+CARTE_FR.deps.map(d=>'<path d="'+d.d+'"><title>'+esc(d.n)+' ('+d.c+')</title></path>').join('')+'</g>';
  h+='<g class="env-regs">'+CARTE_FR.regs.map(d=>'<path d="'+d+'"/>').join('')+'</g>';
  /* des sites voisins (Arras, Noyon…) se recouvraient : on écarte les pastilles et un
     trait fin les relie à leur position réelle (petit point). */
  const R=8.2*f,pts=sites.filter(s=>s.lat&&s.lon).map(s=>{const xy=envXY(Number(s.lat),Number(s.lon));return {s:s,ox:xy[0],oy:xy[1],x:xy[0],y:xy[1]}});
  for(let it=0;it<80;it++)for(let i=0;i<pts.length;i++)for(let j=i+1;j<pts.length;j++){
    const a=pts[i],b=pts[j];let dx=b.x-a.x,dy=b.y-a.y,d=Math.hypot(dx,dy);const min=2*R+1.5*f;
    if(d>=min)continue;if(d<.01){dx=Math.cos(i*2.4+j);dy=Math.sin(i*2.4+j);d=1}
    const p=(min-d)/2/d;a.x-=dx*p;a.y-=dy*p;b.x+=dx*p;b.y+=dy*p}
  pts.forEach(p=>{if(Math.hypot(p.x-p.ox,p.y-p.oy)>2.5*f)h+='<line class="env-fil" x1="'+p.ox.toFixed(1)+'" y1="'+p.oy.toFixed(1)+'" x2="'+p.x.toFixed(1)+'" y2="'+p.y.toFixed(1)+'"/><circle class="env-vrai" cx="'+p.ox.toFixed(1)+'" cy="'+p.oy.toFixed(1)+'" r="'+(1.6*f).toFixed(2)+'"/>'});
  /* le site ouvert est dessiné en dernier : il passe au-dessus de ses voisins */
  pts.sort((a,b)=>(a.s.id===envVue.id)-(b.s.id===envVue.id)).forEach(p=>{
    const s=p.s,r=ENV_REGIMES[s.regime]||ENV_REGIMES.NC,on=s.id===envVue.id,l=ENV_LETTRE[s.regime]||'?';
    h+='<g class="env-pt'+(on?' on':'')+(s.statut==='projet'?' projet':'')+(s.statut==='cessation'?' cess':'')+'" transform="translate('+p.x.toFixed(1)+' '+p.y.toFixed(1)+') scale('+f.toFixed(3)+')" onclick="envOuvrir(\''+s.id+'\')" tabindex="0" onkeydown="if(event.key===\'Enter\')envOuvrir(\''+s.id+'\')">'+
       '<title>'+esc(s.nom)+' — '+esc(r.lib)+'</title>'+
       (on?'<circle r="14" class="halo"/>':'')+
       '<circle r="8.2" fill="'+r.c+'"/><text y="3.2"'+(l.length>1?' class="p"':'')+'>'+l+'</text></g>';
  });
  return h+'</svg>'}
function envLegende(sites){
  let h='<div class="env-leg">';
  Object.keys(ENV_REGIMES).forEach(k=>{
    const n=sites.filter(s=>(s.regime||'NC')===k).length;if(!n&&k==='NC')return;
    h+='<button class="'+(envVue.regime===k?'on':'')+'" onclick="envFiltre(\''+k+'\')" title="N’afficher que ce régime"><i style="background:'+ENV_REGIMES[k].c+'">'+ENV_LETTRE[k]+'</i>'+esc(ENV_REGIMES[k].lib)+' <b>'+n+'</b></button>'});
  return h+'<span class="env-leg-n"><i class="pj"></i>contour pointillé = en projet</span></div>'}
function envFiltre(k){envVue.regime=envVue.regime===k?'':k;renderEnv()}
function envOuvrir(id){envVue.id=id;envVue.onglet='carte';renderEnv()}

/* ---------- fiche d'un site ---------- */
function envChip(txt,c){return '<span class="env-chip" style="--c:'+c+'">'+esc(txt)+'</span>'}
function envLigne(l,v){return v?'<div class="env-l"><span>'+l+'</span><b>'+v+'</b></div>':''}
function envFiche(s){
  const r=ENV_REGIMES[s.regime]||ENV_REGIMES.NC,j=envJours(s.arreteFin),ag=(typeof AGENCES_CDES!=='undefined'?AGENCES_CDES:[]).find(a=>a.code===s.agence);
  let h='<div class="card env-fiche"><div class="env-fh"><button class="btn btn-ghost btn-sm" onclick="envVue.id=null;renderEnv()">← Tous les sites</button>'+
    (estEditeur()?'<button class="btn btn-ghost btn-sm" onclick="envEditer(\''+s.id+'\')">✏️ Modifier</button>':'')+'</div>';
  h+='<h2>'+esc(s.nom)+'</h2><div class="env-chips">'+envChip(r.lib,r.c)+envChip(ENV_STATUTS[s.statut]||ENV_STATUTS.nr,s.statut==='exploitation'?'#158A52':s.statut==='projet'?'#B4720A':'#7b8fa3')+(ag?envChip(s.agence,'#003A6E'):'')+'</div>';
  h+='<div class="env-on">'+ENV_OUINON.map(o=>{const v=s[o[0]];return '<div class="'+(v==='oui'?'oui':v==='non'?'non':'nr')+'"><b>'+(v==='oui'?'✓ Oui':v==='non'?'✗ Non':'—')+'</b><span>'+o[1]+'</span></div>'}).join('')+'</div>';
  if(s.arreteFin)h+='<div class="env-fin '+envTon(j)+'"><span>Fin de validité de l’arrêté</span><b>'+esc(frDate(s.arreteFin))+'</b><em>'+esc(envDans(j))+'</em></div>';
  if(s.okConv==='oui'||s.convNote){const cv=envConv(s);
    h+='<div class="env-cv"><span>Convention avec le propriétaire</span>'+
      (s.convFin?'<b class="'+(cv&&cv.etat==='echue'?'ech':'')+'">'+(cv&&cv.etat==='cours'?'jusqu’au ':'échue le ')+esc(frDate(s.convFin))+'</b>':'')+
      '<em>'+esc([s.convDate?'signée le '+frDate(s.convDate):'',s.convTacite==='oui'?'tacite reconduction':s.convTacite==='non'?'sans tacite reconduction':'',s.convPreavis?'préavis '+s.convPreavis:'',cv&&cv.etat==='reconduite'?'prochaine date anniversaire : '+frDate(cv.date):''].filter(Boolean).join(' · '))+'</em>'+
      (s.convNote?'<em>'+esc(s.convNote)+'</em>':'')+'</div>'}
  h+=envLigne('Commune',esc([s.commune,s.cp?'('+s.cp+')':''].filter(Boolean).join(' ')));
  h+=envLigne('Activité',esc(s.activite));
  h+=envLigne('Parcelles',esc(s.parcelles));
  h+=envLigne('Rubriques ICPE',esc(s.rubriques));
  h+=envLigne('Déclaration',esc([s.declDate?'du '+frDate(s.declDate):'',s.declRef?'réf. '+s.declRef:''].filter(Boolean).join(' — ')));
  h+=envLigne('Arrêté',esc([s.arreteNum?'n° '+s.arreteNum:'',s.arreteDate?'du '+frDate(s.arreteDate):''].filter(Boolean).join(' ')));
  h+=envLigne('Dépôt du renouvellement',s.renouvDepot?esc('avant le '+frDate(s.renouvDepot)):'');
  h+=envLigne('Surface / capacité',esc(s.capacite));
  h+=envLigne('Exploitant',esc(s.exploitant));
  h+=envLigne('Inspection',esc(s.inspection));
  h+=envLigne('Référent CDES',esc(s.referent));
  if(s.note)h+='<p class="env-note">'+esc(s.note)+'</p>';
  const liens=[];
  if(/^https:\/\//.test(s.lienArrete||''))liens.push('<a class="btn btn-ghost btn-sm" target="_blank" rel="noopener" href="'+esc(s.lienArrete)+'">📄 Ouvrir l’arrêté</a>');
  if(/^\d{6,12}$/.test(String(s.aiot||'')))liens.push('<a class="btn btn-ghost btn-sm" target="_blank" rel="noopener" href="https://www.georisques.gouv.fr/risques/installations/donnees/details/'+esc(s.aiot)+'">🏛 Fiche Géorisques</a>');
  if(liens.length)h+='<div class="env-liens">'+liens.join('')+'</div>';
  const ech=envEcheances().filter(e=>e.site.id===s.id);
  h+='<h3>📅 Échéances du site</h3>'+(ech.length?ech.map(e=>envLigneEch(e,false)).join(''):'<p class="hint">Aucune échéance renseignée.</p>');
  return h+'</div>'}
function envLigneEch(e,avecSite){
  const j=envJours(e.date),t=ENV_TYPES[e.type];
  return '<div class="env-e '+envTon(j)+(envVue.jour===e.date?' vise':'')+'"'+(avecSite?' onclick="envOuvrir(\''+e.site.id+'\')" title="Ouvrir la fiche du site"':'')+'>'+
    '<i style="background:'+t.c+'" title="'+esc(t.lib)+'"></i>'+
    '<div class="env-ed"><b>'+esc(frDate(e.date))+'</b><em>'+esc(envDans(j))+'</em></div>'+
    '<div class="env-et">'+(avecSite?'<b>'+esc(e.site.nom)+'</b>':'')+'<span>'+esc(e.lib)+(e.per?' · '+esc((ENV_PERIODES.find(p=>p[0]===e.per)||[0,''])[1].toLowerCase()):'')+'</span></div>'+
    (estEditeur()&&e.id?'<button class="btn btn-ghost btn-sm" onclick="event.stopPropagation();envFait(\''+e.site.id+'\',\''+e.id+'\')" title="'+(e.per?'Fait : la prochaine échéance est reportée automatiquement':'Fait : l’échéance est retirée du calendrier')+'">✓ Fait</button>':'')+
    '</div>'}
function envListeSites(sites){
  if(!sites.length)return '<div class="card"><p class="hint">Aucun site pour ce filtre.</p></div>';
  return '<div class="card env-liste"><h2>'+sites.length+' site'+(sites.length>1?'s':'')+' ICPE</h2>'+sites.map(s=>{
    const r=ENV_REGIMES[s.regime]||ENV_REGIMES.NC,j=envJours(s.arreteFin);
    return '<button class="env-s" onclick="envOuvrir(\''+s.id+'\')"><i style="background:'+r.c+'">'+(ENV_LETTRE[s.regime]||'?')+'</i>'+
      '<span><b>'+esc(s.nom)+'</b><em>'+esc([s.commune,s.cp?'('+String(s.cp).slice(0,2)+')':''].filter(Boolean).join(' '))+(s.statut==='projet'||s.statut==='cessation'?' · '+esc(ENV_STATUTS[s.statut]):'')+'</em></span>'+
      (s.okExploit==='oui'?'<u class="ok" title="Site exploitable">✓</u>':s.okExploit==='non'?'<u class="ko" title="Site non exploitable">✗</u>':'')+(s.arreteFin?'<u class="'+envTon(j)+'">arrêté<br>'+esc(String(s.arreteFin).slice(0,4))+'</u>':'')+'</button>'}).join('')+
    (sites.some(s=>!(s.lat&&s.lon))?'<p class="hint">⚠️ Un site sans coordonnées n’apparaît pas sur la carte.</p>':'')+'</div>'}

/* ---------- calendrier de l'année ---------- */
function envCalendrier(ech){
  const an=envVue.annee,parJour={};
  ech.forEach(e=>{(parJour[e.date]=parJour[e.date]||[]).push(e)});
  const rang={arrete:0,conv:1,suivi:2,libre:3};
  let h='<div class="env-cal">';
  for(let m=0;m<12;m++){
    const n=new Date(an,m+1,0).getDate(),dec=(new Date(an,m,1).getDay()+6)%7;
    const nb=ech.filter(e=>e.date.slice(0,7)===an+'-'+String(m+1).padStart(2,'0')).length;
    h+='<div class="env-m'+(nb?' a':'')+'"><div class="env-mt">'+MOIS_L[m]+(nb?'<b>'+nb+'</b>':'')+'</div><div class="env-mg">'+['L','M','M','J','V','S','D'].map(x=>'<s>'+x+'</s>').join('');
    for(let i=0;i<dec;i++)h+='<span></span>';
    for(let d=1;d<=n;d++){
      const iso=an+'-'+String(m+1).padStart(2,'0')+'-'+String(d).padStart(2,'0'),l=parJour[iso];
      if(l){const t=l.slice().sort((a,b)=>rang[a.type]-rang[b.type])[0];
        h+='<button class="j'+(iso===envVue.jour?' on':'')+'" style="--c:'+ENV_TYPES[t.type].c+'" onclick="envJour(\''+iso+'\')" title="'+esc(l.map(e=>e.site.nom+' — '+e.lib).join('\n'))+'">'+d+(l.length>1?'<sup>'+l.length+'</sup>':'')+'</button>'}
      else h+='<span class="'+(iso===todayISO?'auj':'')+'">'+d+'</span>';
    }
    h+='</div></div>'}
  return h+'</div>'}
function envJour(iso){envVue.jour=envVue.jour===iso?'':iso;renderEnv();const el=document.querySelector('.env-e.vise');if(el)el.scrollIntoView({block:'nearest'})}
function envAnnee(d){envVue.annee+=d;envVue.jour='';renderEnv()}

/* ---------- écran ---------- */
function renderEnv(){
  const box=document.getElementById('v-env');if(!box)return;
  const tous=envSites(),sites=envVue.regime?tous.filter(s=>(s.regime||'NC')===envVue.regime):tous,ech=envEcheances();
  /* à l'ouverture, le calendrier se place sur l'année de la prochaine échéance */
  if(!envVue.annee){const p=ech.find(e=>envJours(e.date)>=0);envVue.annee=p?Number(p.date.slice(0,4)):new Date().getFullYear()}
  const retard=ech.filter(e=>envJours(e.date)<0).length,proches=ech.filter(e=>{const j=envJours(e.date);return j>=0&&j<=90}).length;
  let h='<div class="env-top no-print"><button class="btn btn-ghost" onclick="go(\'v-hub\')">← Accueil</button>'+
    '<h2>🌱 Environnement — sites ICPE</h2>'+
    '<span class="seg"><button class="'+(envVue.onglet==='carte'?'on':'')+'" onclick="envVue.onglet=\'carte\';renderEnv()">🗺 Carte des sites</button>'+
    '<button class="'+(envVue.onglet==='cal'?'on':'')+'" onclick="envVue.onglet=\'cal\';renderEnv()">📅 Échéances'+(retard?' <b class="env-pastille tard">'+retard+'</b>':proches?' <b class="env-pastille">'+proches+'</b>':'')+'</button></span>'+
    (estEditeur()?'<button class="btn btn-primary btn-sm" onclick="envEditer()">＋ Ajouter un site</button><label class="btn btn-ghost btn-sm" title="Importer un fichier de sites (.json) préparé par le service HSE">📥 Importer<input type="file" accept=".json,application/json" style="display:none" onchange="envImporter(this)"></label>':'')+'</div><div id="env-import-etat"></div>';
  if(!tous.length){box.innerHTML=h+'<div class="card"><p class="hint">Aucun site enregistré'+(estEditeur()?' — commence par « ＋ Ajouter un site ».':'.')+'</p></div>';return}
  if(envVue.onglet==='carte'){
    const s=envVue.id?envSite(envVue.id):null;
    h+='<div class="env-grid"><div class="card env-cc"><div class="env-zm no-print"><span class="seg"><button class="'+(envVue.zoom?'':'on')+'" onclick="envVue.zoom=false;renderEnv()">France entière</button><button class="'+(envVue.zoom?'on':'')+'" onclick="envVue.zoom=true;renderEnv()">🔍 Zoom sur les sites</button></span></div>'+envCarte(sites)+envLegende(tous)+'</div><div class="env-side">'+(s?envFiche(s):envListeSites(sites))+'</div></div>';
  }else{
    const an=String(envVue.annee),duJour=envVue.jour?ech.filter(e=>e.date===envVue.jour):null;
    const avant=ech.filter(e=>envJours(e.date)<0),aVenir=ech.filter(e=>envJours(e.date)>=0);
    h+='<div class="env-grid cal"><div class="card"><div class="env-an"><button class="btn btn-ghost btn-sm" onclick="envAnnee(-1)">‹</button><h2>'+an+'</h2><button class="btn btn-ghost btn-sm" onclick="envAnnee(1)">›</button>'+
      '<span class="env-leg2">'+Object.keys(ENV_TYPES).map(k=>'<span><i style="background:'+ENV_TYPES[k].c+'"></i>'+esc(ENV_TYPES[k].lib)+'</span>').join('')+'</span></div>'+
      envCalendrier(ech)+'</div>';
    h+='<div class="env-side"><div class="card env-recap"><h2>Récapitulatif des échéances</h2>';
    if(duJour)h+='<div class="env-rt">Le '+esc(frDate(envVue.jour))+' <button class="btn btn-ghost btn-sm" onclick="envJour(\''+envVue.jour+'\')">Tout revoir</button></div>'+duJour.map(e=>envLigneEch(e,true)).join('');
    else{
      if(avant.length)h+='<div class="env-rt tard">⚠️ En retard ('+avant.length+')</div>'+avant.map(e=>envLigneEch(e,true)).join('');
      h+='<div class="env-rt">À venir ('+aVenir.length+')</div>'+(aVenir.length?aVenir.map(e=>envLigneEch(e,true)).join(''):'<p class="hint">Rien à venir.</p>');
    }
    h+='</div></div></div>';
  }
  box.innerHTML=h}

/* ---------- formulaire (service HSE) ---------- */
function envEditer(id){
  if(!estEditeur()){toast('Réservé au service HSE',true);return}
  const s=id?envSite(id):null;
  envForm=s?JSON.parse(JSON.stringify(s)):{id:'',nom:'',statut:'nr',regime:'D',agence:'',echeances:[]};
  if(!Array.isArray(envForm.echeances))envForm.echeances=[];
  let m=document.getElementById('m-env');
  if(!m){m=document.createElement('div');m.className='modal';m.id='m-env';document.body.appendChild(m)}
  const F=envForm,v=k=>esc(F[k]==null?'':F[k]),opt=(o,sel)=>Object.keys(o).map(k=>'<option value="'+k+'"'+(k===sel?' selected':'')+'>'+esc(typeof o[k]==='string'?o[k]:o[k].lib)+'</option>').join('');
  const ags=(typeof AGENCES_CDES!=='undefined'?AGENCES_CDES:[]);
  m.innerHTML='<div class="sheet env-form" style="max-width:760px"><div class="grab"></div><h2>'+(s?'Modifier le site':'Nouveau site ICPE')+'</h2>'+
    '<label class="f">Nom du site *</label><input type="text" id="ef-nom" value="'+v('nom')+'" placeholder="ex. Terrain de dépôt de …">'+
    '<div class="env-2"><div><label class="f">Régime</label><select id="ef-regime">'+opt(ENV_REGIMES,F.regime||'NC')+'</select></div>'+
    '<div><label class="f">Statut</label><select id="ef-statut">'+opt(ENV_STATUTS,F.statut||'nr')+'</select></div>'+
    '<div><label class="f">Agence</label><select id="ef-agence"><option value="">—</option>'+ags.map(a=>'<option value="'+a.code+'"'+(a.code===F.agence?' selected':'')+'>'+a.code+'</option>').join('')+'</select></div></div>'+
    '<div class="env-2"><div style="flex:2"><label class="f">Commune *</label><input type="text" id="ef-commune" value="'+v('commune')+'"></div>'+
    '<div><label class="f">Code postal</label><input type="text" id="ef-cp" value="'+v('cp')+'" inputmode="numeric" maxlength="5"></div>'+
    '<div style="align-self:flex-end"><button class="btn btn-ghost" onclick="envGeocoder()" title="Cherche les coordonnées de la commune (service public geo.api.gouv.fr)">📍 Placer</button></div></div>'+
    '<div class="env-2"><div><label class="f">Latitude</label><input type="text" id="ef-lat" value="'+v('lat')+'" placeholder="48.97"></div>'+
    '<div><label class="f">Longitude</label><input type="text" id="ef-lon" value="'+v('lon')+'" placeholder="3.18"></div></div>'+
    '<p class="hint" id="ef-geo">Le bouton « 📍 Placer » remplit les coordonnées à partir de la commune. Pour le point exact : clic droit sur Google Maps ▸ copier les deux nombres.</p>'+
    '<h3 style="margin-top:14px">Carte d’identité — oui / non</h3><div class="env-2">'+ENV_OUINON.map(o=>'<div><label class="f">'+o[1]+'</label><select id="ef-'+o[0]+'"><option value="">— à renseigner</option><option value="oui"'+(F[o[0]]==='oui'?' selected':'')+'>Oui</option><option value="non"'+(F[o[0]]==='non'?' selected':'')+'>Non</option></select></div>').join('')+'</div>'+
    '<div class="env-2"><div><label class="f">Convention signée le</label><input type="date" id="ef-convDate" value="'+v('convDate')+'"></div>'+
    '<div><label class="f">Fin de convention</label><input type="date" id="ef-convFin" value="'+v('convFin')+'"></div>'+
    '<div><label class="f">Tacite reconduction</label><select id="ef-convTacite"><option value="">—</option><option value="oui"'+(F.convTacite==='oui'?' selected':'')+'>Oui</option><option value="non"'+(F.convTacite==='non'?' selected':'')+'>Non</option></select></div>'+
    '<div><label class="f">Préavis</label><input type="text" id="ef-convPreavis" value="'+v('convPreavis')+'" placeholder="ex. 1 an, 6 mois"></div></div>'+
    '<label class="f">Précision sur la convention</label><input type="text" id="ef-convNote" value="'+v('convNote')+'" placeholder="ex. même propriétaire que…, CDES propriétaire">'+
    '<label class="f">Activité</label><input type="text" id="ef-activite" value="'+v('activite')+'" placeholder="ex. Transit et valorisation de sédiments">'+
    '<div class="env-2"><div><label class="f">Rubriques ICPE</label><input type="text" id="ef-rubriques" value="'+v('rubriques')+'" placeholder="ex. 2517-2"></div>'+
    '<div><label class="f">Parcelles</label><input type="text" id="ef-parcelles" value="'+v('parcelles')+'" placeholder="ex. ZM 91, ZM 92"></div></div>'+
    '<div class="env-2"><div><label class="f">Date de la déclaration</label><input type="date" id="ef-declDate" value="'+v('declDate')+'"></div>'+
    '<div><label class="f">Référence du dossier (preuve de dépôt)</label><input type="text" id="ef-declRef" value="'+v('declRef')+'"></div></div>'+
    '<div class="env-2"><div><label class="f">N° de l’arrêté</label><input type="text" id="ef-arreteNum" value="'+v('arreteNum')+'"></div>'+
    '<div><label class="f">Date de l’arrêté</label><input type="date" id="ef-arreteDate" value="'+v('arreteDate')+'"></div></div>'+
    '<div class="env-2"><div><label class="f">Fin de validité de l’arrêté</label><input type="date" id="ef-arreteFin" value="'+v('arreteFin')+'"></div>'+
    '<div><label class="f">Dépôt du renouvellement avant le</label><input type="date" id="ef-renouvDepot" value="'+v('renouvDepot')+'"></div></div>'+
    '<div class="env-2"><div><label class="f">Surface / capacité</label><input type="text" id="ef-capacite" value="'+v('capacite')+'" placeholder="ex. 10 000 m²"></div>'+
    '<div><label class="f">Exploitant</label><input type="text" id="ef-exploitant" value="'+v('exploitant')+'" placeholder="CDES"></div></div>'+
    '<div class="env-2"><div><label class="f">Inspection (service)</label><input type="text" id="ef-inspection" value="'+v('inspection')+'" placeholder="ex. DREAL — UD de …"></div>'+
    '<div><label class="f">Référent CDES</label><input type="text" id="ef-referent" value="'+v('referent')+'"></div></div>'+
    '<div class="env-2"><div style="flex:2"><label class="f">Lien de l’arrêté (SharePoint)</label><input type="text" id="ef-lienArrete" value="'+v('lienArrete')+'" placeholder="https://cdes.sharepoint.com/…"></div>'+
    '<div><label class="f">Code AIOT (Géorisques)</label><input type="text" id="ef-aiot" value="'+v('aiot')+'" inputmode="numeric"></div></div>'+
    '<label class="f">Note</label><textarea id="ef-note" rows="2">'+v('note')+'</textarea>'+
    '<h3 style="margin-top:14px">📅 Suivis périodiques et autres échéances</h3><div id="ef-ech"></div>'+
    '<button class="btn btn-ghost btn-sm" onclick="envAjouterEch()">＋ Ajouter une échéance</button>'+
    '<div class="row" style="margin-top:16px">'+(s?'<button class="btn btn-danger" onclick="envRetirer(\''+s.id+'\')">🗑</button>':'')+
    '<button class="btn btn-ghost grow" onclick="closeModal()">Annuler</button><button class="btn btn-primary grow" id="ef-ok" onclick="envEnregistrer()">Enregistrer</button></div></div>';
  envRendreEch();m.classList.add('open')}
function envRendreEch(){
  const z=document.getElementById('ef-ech');if(!z)return;
  z.innerHTML=envForm.echeances.filter(e=>!e.fait).map(e=>'<div class="env-fe" data-id="'+e.id+'">'+
    '<select class="fe-type"><option value="suivi"'+(e.type!=='libre'?' selected':'')+'>Suivi périodique</option><option value="libre"'+(e.type==='libre'?' selected':'')+'>Autre échéance</option></select>'+
    '<input type="text" class="fe-lib" value="'+esc(e.lib||'')+'" placeholder="ex. Analyses des eaux, bilan annuel à la DREAL…">'+
    '<input type="date" class="fe-date" value="'+esc(e.date||'')+'">'+
    '<select class="fe-per">'+ENV_PERIODES.map(p=>'<option value="'+p[0]+'"'+(Number(e.per||0)===p[0]?' selected':'')+'>'+p[1]+'</option>').join('')+'</select>'+
    '<button class="btn btn-danger btn-sm" onclick="envLireEch();envForm.echeances=envForm.echeances.filter(x=>x.id!==\''+e.id+'\');envRendreEch()" title="Retirer">✕</button></div>').join('')||'<p class="hint">Aucune pour l’instant.</p>'}
function envLireEch(){
  document.querySelectorAll('#ef-ech .env-fe').forEach(l=>{const e=envForm.echeances.find(x=>x.id===l.dataset.id);if(!e)return;
    e.type=l.querySelector('.fe-type').value;e.lib=l.querySelector('.fe-lib').value.trim();e.date=l.querySelector('.fe-date').value;e.per=Number(l.querySelector('.fe-per').value)||0})}
function envAjouterEch(){envLireEch();envForm.echeances.push({id:uid(),type:'suivi',lib:'',date:'',per:12});envRendreEch()}
async function envGeocoder(){
  const c=document.getElementById('ef-commune').value.trim(),cp=document.getElementById('ef-cp').value.trim(),z=document.getElementById('ef-geo');
  if(!c&&!cp){toast('Renseigne la commune ou le code postal',true);return}
  z.textContent='⏳ Recherche de la commune…';
  try{
    const r=await fetch('https://geo.api.gouv.fr/communes?'+(c?'nom='+encodeURIComponent(c)+'&':'')+(cp?'codePostal='+encodeURIComponent(cp)+'&':'')+'fields=nom,centre,codesPostaux&boost=population&limit=1');
    const l=await r.json();if(!l||!l[0]||!l[0].centre)throw new Error('commune introuvable');
    const xy=l[0].centre.coordinates;
    document.getElementById('ef-lat').value=xy[1].toFixed(4);document.getElementById('ef-lon').value=xy[0].toFixed(4);
    if(!c)document.getElementById('ef-commune').value=l[0].nom;
    if(!cp&&l[0].codesPostaux&&l[0].codesPostaux[0])document.getElementById('ef-cp').value=l[0].codesPostaux[0];
    z.textContent='✓ Placé au centre de '+l[0].nom+'. Ajuste les coordonnées si le site est à l’écart du bourg.';
  }catch(e){z.textContent='⚠️ Recherche impossible ('+(e.message||'réseau')+') — saisis latitude et longitude à la main.'}}
function envLocal(){return typeof appel!=='function'||(typeof demoMode==='function'&&demoMode())}
async function envPousser(site,suppr){
  if(envLocal()){
    state.sitesEnv=(state.sitesEnv||[]).filter(s=>s.id!==site.id);if(!suppr)state.sitesEnv.push(site);save();return}
  const j=await appel({secret:conf.secret,action:suppr?'env-suppr':'env-maj',appareil:conf.appareil||'appareil',data:suppr?{ids:[site.id]}:{sites:[site]}},45000);
  if(!j||!j.ok)throw new Error((j&&j.erreur)||'refusé');
  if(j.data&&Array.isArray(j.data.sitesEnv))state.sitesEnv=j.data.sitesEnv;save()}
async function envEnregistrer(){
  if(envEnvoi)return;
  const g=k=>document.getElementById('ef-'+k).value.trim(),F=envForm;
  ['nom','regime','statut','agence','commune','cp','activite','rubriques','arreteNum','arreteDate','arreteFin','renouvDepot','capacite','exploitant','inspection','referent','lienArrete','aiot','note','parcelles','declDate','declRef','okExploit','okDecl','okDossier','okConv','convDate','convFin','convTacite','convPreavis','convNote'].forEach(k=>F[k]=g(k));
  const num=t=>{const n=parseFloat(String(t).replace(',','.'));return isFinite(n)?n:''};
  F.lat=num(g('lat'));F.lon=num(g('lon'));
  envLireEch();F.echeances=F.echeances.filter(e=>e.fait||(e.lib&&e.date));
  if(!F.nom||!F.commune){toast('Le nom et la commune sont obligatoires',true);return}
  if(F.lienArrete&&!/^https:\/\//.test(F.lienArrete)){toast('Le lien de l’arrêté doit commencer par https://',true);return}
  if((F.lat!==''&&(F.lat<41||F.lat>51.5))||(F.lon!==''&&(F.lon<-5.5||F.lon>10))){toast('Coordonnées hors de France métropolitaine — vérifie latitude / longitude',true);return}
  if(!F.id)F.id=uid();F.maj=nowISO();
  const b=document.getElementById('ef-ok');envEnvoi=true;if(b){b.disabled=true;b.textContent='Enregistrement…'}
  try{await envPousser(F,false);closeModal();envVue.id=F.id;envVue.onglet='carte';renderEnv();toast('Site enregistré ✓')}
  catch(e){toast('Échec : '+(e.message||'?')+' — rien n’est perdu, réessaie',true);if(b){b.disabled=false;b.textContent='Enregistrer'}}
  finally{envEnvoi=false}}
async function envRetirer(id){
  const s=envSite(id);if(!s||!estEditeur())return;
  if(!confirm('Retirer le site « '+s.nom+' » de la carte et du calendrier ?'))return;
  try{await envPousser(s,true);closeModal();envVue.id=null;renderEnv();toast('🗑️ Site retiré')}catch(e){toast('Échec : '+(e.message||'?'),true)}}
/* ✓ Fait : une échéance périodique est reportée d'une période, une ponctuelle est close */
async function envFait(idSite,idEch){
  const s=envSite(idSite);if(!s||!estEditeur())return;
  const c=JSON.parse(JSON.stringify(s)),e=(c.echeances||[]).find(x=>x.id===idEch);if(!e)return;
  const per=Number(e.per)||0;let suite='';
  if(per){const d=new Date(e.date+'T12:00');d.setMonth(d.getMonth()+per);suite=d.toISOString().slice(0,10)}
  if(!confirm('« '+e.lib+' » — '+s.nom+'\n\nMarquer comme fait ?'+(suite?'\nProchaine échéance : '+frDate(suite)+'.':'')))return;
  e.dernierFait=todayISO;if(suite)e.date=suite;else e.fait=true;c.maj=nowISO();
  try{await envPousser(c,false);renderEnv();toast(suite?'Fait ✓ — prochaine le '+frDate(suite):'Fait ✓')}catch(err){toast('Échec : '+(err.message||'?'),true)}}

/* ---------- import (éditeur) d'un fichier de sites ----------
   Les sites déjà présents (même identifiant) ne sont PAS écrasés : relancer l'import est sans risque. */
async function envImporter(inp){
  const fichier=inp.files&&inp.files[0];inp.value='';if(!fichier)return;
  if(!estEditeur()){toast('Réservé au service HSE',true);return}
  let d;try{d=JSON.parse(await fichier.text())}catch(e){toast('Fichier illisible',true);return}
  if(!d||d.format!=='sites-icpe-cdes-v1'||!Array.isArray(d.sites)){toast('Ce n’est pas un fichier d’import de sites ICPE',true);return}
  const deja={};(state.sitesEnv||[]).forEach(s=>deja[s.id]=1);
  const a=d.sites.filter(s=>s&&s.id&&s.nom&&!deja[s.id]);
  if(!a.length){toast('Tout est déjà importé ('+d.sites.length+' sites)');return}
  if(!confirm('Importer '+a.length+' site'+(a.length>1?'s':'')+(d.sites.length-a.length?' ('+(d.sites.length-a.length)+' déjà présents, ignorés)':'')+' ?'))return;
  const zone=()=>document.getElementById('env-import-etat');let ok=0;
  try{
    for(let i=0;i<a.length;i+=10){
      if(zone())zone().innerHTML='<div class="banner info" style="color:var(--cyan)">📥 Import '+Math.min(i+10,a.length)+' / '+a.length+'…</div>';
      const lot=a.slice(i,i+10);
      if(envLocal()){state.sitesEnv=(state.sitesEnv||[]).concat(lot);save()}
      else{const j=await appel({secret:conf.secret,action:'env-maj',appareil:conf.appareil||'appareil',data:{sites:lot}},60000);
        if(!j||!j.ok)throw new Error((j&&j.erreur)||'refusé');
        if(j.data&&Array.isArray(j.data.sitesEnv))state.sitesEnv=j.data.sitesEnv;save()}
      ok+=lot.length}
    renderEnv();if(zone())zone().innerHTML='<div class="banner ok">✓ '+ok+' site'+(ok>1?'s':'')+' importé'+(ok>1?'s':'')+'.</div>';
  }catch(e){renderEnv();if(zone())zone().innerHTML='<div class="banner">Import interrompu après '+ok+' site(s) : '+esc(e.message||'?')+'. Relance l’import : ce qui est passé ne sera pas refait.</div>'}
}
